insert into public.products(slug,category,name,img,from_price,unit,featured,short,long,specs,variants,sort) values('ss-stool','furniture','Stainless Steel Stool','assets/img/ss-stool.jpg',2800,'Piece',true,'Tapered four-leg stool with a seamless round seat and double footrest bracing.','A workshop and cleanroom stool built from SS 304 square section with a fully welded, ground and buffed frame. The round seat is pressed from 1.5 mm sheet and rolled over at the edge so there is no exposed sharp lip, and the underside is closed off to stop dust settling. Legs splay outward for stability under lateral load and carry two levels of bracing — an upper mid-rail and a full perimeter foot ring. Feet are fitted with welded SS pads that can be swapped for levelling bolts or nylon glides on request.','[["Material","SS 304 (SS 316 on request)"],["Seat","1.5 mm pressed sheet, rolled edge"],["Frame","25 × 25 mm square section, 1.5 mm"],["Finish","Matt buff / mirror polish"],["Load rating","150 kg static"],["Origin","Made in India"]]'::jsonb,'[{"name":"Low stool — 18 in seat height","d":"Ø 300 mm seat","price":2800},{"name":"Counter stool — 24 in seat height","d":"Ø 320 mm seat","price":3400},{"name":"Bar stool — 30 in seat height","d":"Ø 350 mm seat, foot ring","price":4100},{"name":"Heavy-duty stool — 24 in","d":"2 mm frame, 200 kg rating","price":5200},{"name":"Height-adjustable stool","d":"450–600 mm, gas lift","price":6800}]'::jsonb,0) on conflict (slug) do nothing;
insert into public.products(slug,category,name,img,from_price,unit,featured,short,long,specs,variants,sort) values('ss-chair','furniture','Stainless Steel Chair','assets/img/ss-chair.jpg',3500,'Piece',true,'Fixed-back SS chair for laboratories, QC rooms and production lines.','A fixed chair in SS 304 round pipe with a pressed seat and contoured back rest. All joints are TIG welded and ground flush so the frame wipes down clean, which is why it is the standard seating in most of the pharmaceutical units we supply. The foot ring doubles as a rest and stiffens the frame. Available with or without a back, and with a perforated seat where wash-down is frequent.','[["Material","SS 304"],["Frame","25 mm round pipe, 1.6 mm"],["Seat","Pressed sheet, 1.5 mm"],["Back","Fixed, contoured"],["Finish","Matt buff"],["Chair type","Normal fix chair"]]'::jsonb,'[{"name":"Standard fix chair","d":"18 in seat height, with back","price":3500},{"name":"High chair with back","d":"24 in seat height, foot ring","price":4200},{"name":"Revolving lab chair","d":"Gas lift, castor base","price":7500},{"name":"Perforated seat chair","d":"For wash-down areas","price":4600}]'::jsonb,1) on conflict (slug) do nothing;
insert into public.products(slug,category,name,img,from_price,unit,featured,short,long,specs,variants,sort) values('ss-table-cabinet','furniture','Silver Stainless Steel Table Cabinet','assets/img/ss-table-cabinet.jpg',25000,'Piece',true,'Under-counter storage cabinet with hinged doors and a working top.','A laboratory storage cabinet with a flat working top and hinged doors below, made to sit against a wall as a run of base units. The carcass is double-skinned with a coved internal bottom so spillage does not collect in corners. Shelves are removable for cleaning and can be set at 50 mm pitch. Doors take a flush recessed handle and an optional key lock. We build these to your wall dimension rather than a fixed size, so the run finishes without a filler gap.','[["Material","SS 304"],["Usage","Laboratory, QC room, production"],["Doors","Hinged, flush handle"],["Top","1.2 mm, 40 mm coved edge"],["Shelves","Removable, adjustable"],["Legs","Adjustable bullet feet"]]'::jsonb,'[{"name":"2-door cabinet","d":"1200 × 600 × 850 mm","price":25000},{"name":"3-door cabinet","d":"1800 × 600 × 850 mm","price":34000},{"name":"4-door cabinet","d":"2400 × 600 × 850 mm","price":42000},{"name":"Custom length run","d":"Built to your wall dimension","price":null}]'::jsonb,2) on conflict (slug) do nothing;
insert into public.products(slug,category,name,img,from_price,unit,featured,short,long,specs,variants,sort) values('cross-over-bench','furniture','Cross Over Bench',null,12000,'Piece',false,'Change-room bench that separates the shoe-off and shoe-on side of an entry.','A cross-over bench defines the clean boundary at a change room door. An operator sits on the outer side, removes outdoor footwear, swings across the bench and puts on plant footwear on the clean side — so the two floors never share a shoe. Built in SS 304 with a slatted or solid top, optional shoe racks underneath and a footwear stopper strip along the centre line.','[["Material","SS 304"],["Top","Solid or slatted"],["Racks","Optional, both sides"],["Fixing","Floor mounted or free standing"],["Finish","Matt buff"]]'::jsonb,'[{"name":"2-seater bench","d":"900 mm long","price":12000},{"name":"4-seater bench","d":"1500 mm long","price":18000},{"name":"6-seater bench","d":"2100 mm long","price":24000},{"name":"With shoe rack","d":"Any length, twin-tier rack","price":null}]'::jsonb,3) on conflict (slug) do nothing;
insert into public.products(slug,category,name,img,from_price,unit,featured,short,long,specs,variants,sort) values('ss-locker','lockers','Stainless Steel Locker','assets/img/ss-locker.jpg',60000,'Piece',true,'Multi-compartment personnel locker with hinged doors and key locks.','A personnel locker for change rooms where powder-coated MS is not acceptable. The body is folded from SS 304 sheet with a fully welded and ground frame, hinged doors on concealed pins and a key lock per compartment. Each compartment has a louvred vent for air movement and a name-card holder. The unit stands on a 100 mm skirt so the floor can be washed under it, and can be bolted back-to-back in a double row.','[["Material","Stainless Steel 304"],["Lock type","Key lock, per compartment"],["Door type","Hinged"],["Usage","Office, plant change room"],["Colour","Silver"],["Finish","Polished"]]'::jsonb,'[{"name":"6-compartment locker","d":"900 × 450 × 1800 mm","price":34000},{"name":"12-compartment locker","d":"900 × 450 × 1800 mm","price":46000},{"name":"18-compartment locker","d":"1200 × 450 × 1980 mm","price":60000},{"name":"24-compartment locker","d":"1200 × 450 × 1980 mm","price":72000},{"name":"Custom compartment layout","d":"Built to your drawing","price":null}]'::jsonb,4) on conflict (slug) do nothing;
insert into public.products(slug,category,name,img,from_price,unit,featured,short,long,specs,variants,sort) values('ss-mobile-locker','lockers','Stainless Steel Mobile Locker','assets/img/ss-mobile-locker.jpg',25000,'Piece',false,'Castor-mounted locker bank that rolls out of the way for floor cleaning.','The same locker construction on a heavy castor base, so a whole bank can be pulled clear of the wall during wash-down and pushed back afterwards. Two castors are braked. Sized for shift-wise personal storage in food and pharma units where the floor is cleaned every shift.','[["Material","S.S. 304"],["Lock type","Key lock"],["Capacity","15 Litre per compartment"],["Castors","100 mm, 2 braked"],["Usage","Office, plant"],["Country of origin","Made in India"]]'::jsonb,'[{"name":"8-compartment mobile locker","d":"15 L compartments","price":25000},{"name":"16-compartment mobile locker","d":"15 L compartments","price":38000},{"name":"Mobile locker with tray shelf","d":"Top tray + 12 compartments","price":44000}]'::jsonb,5) on conflict (slug) do nothing;
insert into public.products(slug,category,name,img,from_price,unit,featured,short,long,specs,variants,sort) values('storage-locker','lockers','Document Storage Locker',null,28000,'Piece',false,'Full-height cupboard for batch records, tooling and change parts.','A full-height two-door cupboard with adjustable shelves, used for batch record storage, change parts and tooling. Doors close on a full-length SS piano hinge and take a three-point lock. Interior shelves are removable and set on a 50 mm pitch. Where records must be traceable, we fit a sealed hasp point for a tamper tag.','[["Material","SS 304"],["Shelves","4 adjustable"],["Lock","3-point, key"],["Hinge","Full-length piano hinge"],["Height","1980 mm standard"]]'::jsonb,'[{"name":"Single-door cupboard","d":"600 × 450 × 1980 mm","price":28000},{"name":"2-door cupboard","d":"900 × 450 × 1980 mm","price":38000},{"name":"2-door wide cupboard","d":"1200 × 500 × 1980 mm","price":47000}]'::jsonb,6) on conflict (slug) do nothing;
insert into public.products(slug,category,name,img,from_price,unit,featured,short,long,specs,variants,sort) values('ss-mixing-tank','tanks','Stainless Steel Mixing Tank',null,85000,'Piece',true,'Agitated process tank from 50 L to 10,000 L with dished ends and CIP spray ball.','A cylindrical mixing tank with a dished top and conical or dished bottom, agitator, and a top-mounted geared drive. Internal surfaces are polished to the finish your process needs — 180 grit as standard, mirror or electropolish where a product contact certificate is required. Standard build includes a CIP spray ball, a manway, level markings, a bottom outlet valve and adjustable legs. Jacket, insulation and cladding are added where heating or cooling is part of the process. Every tank leaves the shop hydro-tested with a dye-penetrant weld report.','[["Material","SS 304 / SS 316 / SS 316L"],["Capacity range","50 L to 10,000 L"],["Internal finish","180 grit; mirror or EP optional"],["Agitator","Anchor, paddle, turbine or high-shear"],["Bottom","Conical or dished"],["Testing","Hydro test + DP weld report"]]'::jsonb,'[{"name":"50 L pilot tank","d":"Portable, castor legs","price":85000},{"name":"200 L mixing tank","d":"Anchor agitator, 0.5 HP","price":145000},{"name":"500 L mixing tank","d":"Anchor agitator, 1 HP","price":210000},{"name":"1,000 L mixing tank","d":"Anchor + scraper, 2 HP","price":320000},{"name":"2,000 L mixing tank","d":"Jacketed, 3 HP","price":520000},{"name":"5,000 L mixing tank","d":"Jacketed + insulated","price":940000},{"name":"10,000 L storage-mix tank","d":"Site-assembled","price":null}]'::jsonb,7) on conflict (slug) do nothing;
insert into public.products(slug,category,name,img,from_price,unit,featured,short,long,specs,variants,sort) values('jacketed-vessel','tanks','Jacketed Vessel',null,165000,'Piece',false,'Limpet or dimple-jacketed vessel for heating and cooling duty.','A jacketed vessel for processes that need controlled heat transfer — syrup preparation, ointment bases, crystallisation. Choose a limpet coil jacket for steam duty at higher pressure, or a dimple jacket where the heat transfer area matters more than pressure. The jacket is pressure tested separately from the shell, and the whole vessel is insulated with 50 mm mineral wool and clad in SS 304 sheet.','[["Jacket type","Limpet coil or dimple"],["Shell material","SS 316 / SS 316L"],["Design pressure","Up to 3.5 kg/cm² jacket"],["Insulation","50 mm mineral wool, SS clad"],["Testing","Shell and jacket tested separately"]]'::jsonb,'[{"name":"100 L jacketed vessel","d":"Limpet coil","price":165000},{"name":"250 L jacketed vessel","d":"Limpet coil","price":240000},{"name":"500 L jacketed vessel","d":"Dimple jacket","price":385000},{"name":"1,000 L jacketed vessel","d":"Limpet + insulation","price":610000},{"name":"2,000 L jacketed vessel","d":"Limpet + insulation","price":890000}]'::jsonb,8) on conflict (slug) do nothing;
insert into public.products(slug,category,name,img,from_price,unit,featured,short,long,specs,variants,sort) values('ss-filling-vessel','pharma','Stainless Steel Filling Vessel','assets/img/ss-filling-vessel.jpg',48000,'Piece',true,'Pressure-rated filling vessel with clamp lid, filter housing and outlet manifold.','A portable filling vessel used to feed liquid filling machines. The clamped lid seals on a silicone gasket, and the vessel takes compressed air through a regulator and 0.2 micron filter so the product is pushed rather than pumped. Fitted with a pressure gauge, safety relief valve, sight glass and a bottom outlet with a tri-clamp connection. Mounted on a castor trolley so it moves between the preparation room and the filling line.','[["Material","SS 316L product contact"],["Lid","Clamped, silicone gasket"],["Air filter","0.2 micron, sterilisable"],["Fittings","Tri-clamp, pressure gauge, relief valve"],["Mobility","Castor trolley, 2 braked"],["Finish","Mirror internal"]]'::jsonb,'[{"name":"25 L filling vessel","d":"Trolley mounted","price":48000},{"name":"50 L filling vessel","d":"Trolley mounted","price":62000},{"name":"100 L filling vessel","d":"Trolley mounted","price":84000},{"name":"200 L filling vessel","d":"Fixed leg","price":118000}]'::jsonb,9) on conflict (slug) do nothing;
insert into public.products(slug,category,name,img,from_price,unit,featured,short,long,specs,variants,sort) values('ss-hopper','pharma','Stainless Steel Hopper',null,32000,'Piece',false,'Conical feed hopper with a clamped lid, sized to your machine inlet.','A conical hopper that sits above a tablet press, capsule filler or packing machine and feeds material by gravity. The cone angle is set to the flow characteristic of your granule so it does not bridge. Internal welds are ground and polished to a continuous radius. The outlet is made to your machine''s inlet diameter, and a butterfly valve or slide gate can be fitted.','[["Material","SS 316 / SS 304"],["Cone angle","60° standard, set to flow"],["Lid","Clamped, hinged option"],["Outlet","To machine inlet dia."],["Finish","Mirror internal, matt external"]]'::jsonb,'[{"name":"25 L hopper","d":"With stand","price":32000},{"name":"50 L hopper","d":"With stand","price":44000},{"name":"100 L hopper","d":"With stand + valve","price":68000},{"name":"200 L hopper","d":"Castor stand + valve","price":96000}]'::jsonb,10) on conflict (slug) do nothing;
insert into public.products(slug,category,name,img,from_price,unit,featured,short,long,specs,variants,sort) values('ss-scoop','pharma','Stainless Steel Scoop',null,850,'Piece',false,'Seamless one-piece scoop with a closed handle — no crevice, no trapped powder.','A dispensing scoop pressed and welded so the handle is sealed at both ends and the bowl has no internal corner. That matters in a dispensing booth: an open handle tube traps powder and cannot be verified as clean. Supplied polished inside and out, and marked with a laser-etched ID number if you keep a cleaning log.','[["Material","SS 316L"],["Handle","Closed, sealed both ends"],["Finish","Mirror polished both sides"],["Marking","Laser etched ID (optional)"],["Sizes","50 ml to 2,000 ml"]]'::jsonb,'[{"name":"50 ml scoop","d":"Short handle","price":850},{"name":"100 ml scoop","d":"Short handle","price":1050},{"name":"250 ml scoop","d":"Standard handle","price":1400},{"name":"500 ml scoop","d":"Standard handle","price":1850},{"name":"1,000 ml scoop","d":"Long handle","price":2600},{"name":"2,000 ml scoop","d":"Long handle","price":3800}]'::jsonb,11) on conflict (slug) do nothing;
insert into public.products(slug,category,name,img,from_price,unit,featured,short,long,specs,variants,sort) values('ss-bucket','pharma','Stainless Steel Bucket',null,1600,'Piece',false,'Seamless drawn bucket with a rolled rim and a swing handle.','A deep-drawn bucket with no side seam, a rolled top rim and a swing handle on welded lugs. Because the body is drawn rather than rolled and welded, there is no vertical seam to hold residue. Used for material transfer, sampling and cleaning solution in GMP areas.','[["Material","SS 304 / SS 316"],["Construction","Deep drawn, seamless body"],["Rim","Rolled"],["Handle","Swing, welded lugs"],["Sizes","5 L to 30 L"]]'::jsonb,'[{"name":"5 L bucket","d":"Seamless","price":1600},{"name":"10 L bucket","d":"Seamless","price":2100},{"name":"15 L bucket","d":"Seamless","price":2600},{"name":"20 L bucket","d":"Seamless","price":3200},{"name":"30 L bucket","d":"With lid","price":4400}]'::jsonb,12) on conflict (slug) do nothing;
insert into public.products(slug,category,name,img,from_price,unit,featured,short,long,specs,variants,sort) values('ss-dustbin-15l','dustbins','15 Litre Stainless Steel Dustbin','assets/img/ss-dustbin-15l.jpg',3200,'Piece',true,'Pedal-operated bin with a removable inner liner and a soft-close lid.','A pedal bin in SS 304 with a lift-out inner bucket, so the outer body never contacts waste and stays presentable. The pedal linkage is a simple bent rod running inside the body — nothing exposed to catch on a mop. The lid closes on a damper so it does not clatter in quiet areas. For segregation, we supply the same body with colour-coded lids and vinyl labelling.','[["Material","SS 304"],["Operation","Foot pedal"],["Liner","Removable inner bucket"],["Lid","Soft close"],["Base","Non-slip ring"],["Capacity","15 L (5 L to 100 L available)"]]'::jsonb,'[{"name":"5 L pedal bin","d":"Bedside / office","price":1800},{"name":"15 L pedal bin","d":"Standard plant bin","price":3200},{"name":"30 L pedal bin","d":"Corridor bin","price":4900},{"name":"50 L pedal bin","d":"Production area","price":7200},{"name":"100 L pedal bin","d":"Bulk waste","price":11500},{"name":"Segregation set (4 bins)","d":"Colour-coded lids + labels","price":16800}]'::jsonb,13) on conflict (slug) do nothing;
insert into public.products(slug,category,name,img,from_price,unit,featured,short,long,specs,variants,sort) values('garbage-trolley','dustbins','Garbage Collection Trolley',null,14500,'Piece',false,'Wheeled waste trolley for moving bagged waste out of production areas.','A four-wheel trolley that carries one or more bin bodies, used to collect waste from a whole floor in a single round. The frame is SS 304 pipe, and the wheels are 150 mm non-marking castors with two brakes. A lid keeps waste covered while it moves through corridors, which most plant audits ask for.','[["Material","SS 304"],["Castors","150 mm non-marking, 2 braked"],["Lid","Hinged, full cover"],["Handle","Push bar, both ends"],["Capacity","100 L to 400 L"]]'::jsonb,'[{"name":"100 L single-bin trolley","d":"One body","price":14500},{"name":"200 L trolley","d":"One body","price":21000},{"name":"2 × 100 L segregation trolley","d":"Two bodies","price":26500},{"name":"400 L bulk trolley","d":"Push bar both ends","price":38000}]'::jsonb,14) on conflict (slug) do nothing;
insert into public.products(slug,category,name,img,from_price,unit,featured,short,long,specs,variants,sort) values('liquid-soap-dispenser','utility','Liquid Soap Dispenser',null,2400,'Piece',false,'Elbow or foot-operated dispenser so clean hands never touch the unit.','A wall-mounted dispenser with a stainless body and a refillable reservoir. The elbow-operated lever is the usual choice at a change-room wash station; where hands must stay entirely free, we supply the same reservoir on a floor stand with a foot pedal. The reservoir lifts out for cleaning and the nozzle unscrews without a tool.','[["Material","SS 304"],["Operation","Elbow lever or foot pedal"],["Capacity","500 ml to 2 L"],["Mounting","Wall plate or floor stand"],["Reservoir","Removable, tool-free nozzle"]]'::jsonb,'[{"name":"500 ml elbow dispenser","d":"Wall mounted","price":2400},{"name":"1 L elbow dispenser","d":"Wall mounted","price":3100},{"name":"2 L elbow dispenser","d":"Wall mounted","price":4200},{"name":"Foot-operated stand dispenser","d":"5 L reservoir","price":9800}]'::jsonb,15) on conflict (slug) do nothing;
insert into public.products(slug,category,name,img,from_price,unit,featured,short,long,specs,variants,sort) values('ss-drain-trap','utility','SS Drain Trap',null,5600,'Piece',false,'Floor drain with a removable basket and a deep water seal.','A floor drain trap set into the finished floor, with a lift-out perforated basket that catches solids before they reach the line. The trap body holds a deep water seal so drain air does not come back into the room, and the grating sits flush so a trolley wheel rolls over it. Supplied with a puddle flange for tiled or epoxy floors.','[["Material","SS 304 / SS 316"],["Basket","Removable, perforated"],["Seal","Deep water seal"],["Grating","Flush, load bearing"],["Flange","Puddle flange included"]]'::jsonb,'[{"name":"4\" square drain trap","d":"100 × 100 mm","price":5600},{"name":"6\" square drain trap","d":"150 × 150 mm","price":7900},{"name":"8\" square drain trap","d":"200 × 200 mm","price":11200},{"name":"Channel drain, per metre","d":"Grating + slope","price":null}]'::jsonb,16) on conflict (slug) do nothing;
